head.script:

	scwin.onpageload = function() {

	};

	scwin.onpageunload = function() {

	};


	scwin.trigger1_onclick = function(e) {
		requires("uiplugin.popup");
		var options1 = { 
		  id : "pop1",			
		  type : "browserPopup",  
		  popupName : "PopUp1",
		  width: "300px",
		  height: "200px",
		  top: "50px",
		  left: "300px"
		}; 

		$p.openPopup("pop1.xml",  options1 );
	};

	scwin.trigger2_onclick = function(e) {
		requires("uiplugin.popup");
		var options2 = { 
		  id : "pop2",		
		  type : "wframePopup", 	 
		  popupName : "PopUp2",
		  width: "300px",
		  height: "200px",
		  top: "50px",
		  left: "600px"
		}; 

		$p.openPopup("pop2.xml",  options2 );

	};

	scwin.trigger3_onclick = function(e) {
		requires("uiplugin.popup");
		var options2 = { 
		  id : "pop3",		
		  type : "iframePopup",
		  popupName : "PopUp3",
		  width: "300px",
		  height: "200px",
		  top: "250px",
		  left: "300px"
		}; 

		$p.openPopup("pop3.xml",  options2 );

	};

	scwin.trigger4_onclick = function(e) {
		window.ax = $p.getPopupWindowList();
        window.bx = $p.getPopupList();
        window.cx = $p.getAllPopupList();
        window.dx = $p.getAllPopupWindowList();
        window.ex = $p.getAllPopupWindowList(true);
        window.fx = $p.getPopupWindowList(true);
		localStorage.setItem('log', ax.length);
        console.log(ax,bx,cx,dx,ex,fx);
	};

	scwin.checkVal1 = function() {
		return localStorage.getItem('log') == 0;
	}		
	scwin.checkVal2 = function() {
		var temp = WebSquare.logger.getErrorLog();
		return temp == '';
	}		
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "400");		
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
	localStorage.removeItem("log");
